const express = require('express');
const fs = require('fs').promises;
const path = require('path');
const db = require('../db');

const app = express();
app.use(express.json());

app.post('/api/wasm/extract-text', async (req, res) => {
  const { documentId } = req.body;
  if (!documentId) {
    return res.status(400).json({ error: 'documentId required' });
  }

  // Check document tenancy before loading from disk
  const docRecord = await db('stored_documents')
    .where({ id: documentId, tenant_id: req.user.tenantId })
    .first();
  if (!docRecord) {
    return res.status(404).json({ error: 'Document not found' });
  }

  const docPath = path.resolve(__dirname, `../docs_storage/${documentId}.pdf`);
  try {
    const docBytes = await fs.readFile(docPath);
    const wasmBytes = await fs.readFile(path.resolve(__dirname, '../wasm/pdf_ocr.wasm'));

    const wasmInstance = (await WebAssembly.instantiate(wasmBytes, {})).instance;
    const { memory, extract } = wasmInstance.exports;

    new Uint8Array(memory.buffer, 0, docBytes.length).set(docBytes);
    const extractedLength = extract(docBytes.length);
    const textResult = new TextDecoder().decode(new Uint8Array(memory.buffer, 0, extractedLength));

    return res.json({ documentId, text: textResult });
  } catch (err) {
    return res.status(500).json({ error: 'Text extraction failed' });
  }
});

module.exports = app;
